import {icon,btn,badge,navLink,sectionHead,escapeHTML as esc} from './ui.js';
import {availableRuntimes,draftProfile,RUNTIME_PROFILES,LANGUAGE_POLICY,submissionProfile} from './runtime-config.js';
export function submissionView(state){
  const profile=draftProfile(state);
  return `<div class="page-heading"><div><div class="eyebrow">UET BOT ARENA / MÙA 2026</div><h1>Nộp bot</h1><p>C++ là lựa chọn mặc định. Thêm một ý tưởng, lưu một phiên bản, thử trước khi đấu.</p></div><div class="page-actions"><a href="${profile.starter}" download class="btn">${icon('download')}Tải bot mẫu ${profile.id==='cpp17'?'C++':'Codon'}</a><a href="#/benchmark" class="btn primary">Test & benchmark</a></div></div>
  <div class="runtime-policy"><span class="runtime-policy-mark">C++</span><div><strong>C++ trước. Python + Codon khi đội chọn.</strong><p>C++17 là luồng mặc định. Python + Codon ${LANGUAGE_POLICY.codonEnabled?'được mở để thử nghiệm theo lựa chọn của đội':'đang tắt cho các phiên bản nộp mới'}. Cả hai cùng nhận observation và trả action qua một protocol.</p></div><span class="badge success">C++ mặc định</span></div>
  <div class="submission-layout"><div class="content-stack"><section class="panel">${sectionHead('Phiên bản mới','Chọn runtime, sau đó đóng gói source thành .zip.')}
  <form id="submission-form"><div class="form-fields runtime-fields"><div class="form-row"><label class="field"><span>Tên phiên bản</span><input class="input" name="version" placeholder="Ví dụ: v1.4.0" required pattern="v?[0-9]+[.][0-9]+[.][0-9]+" value="${esc(state.draftVersion)}" maxlength="24"></label><label class="field"><span>Ngôn ngữ & runtime</span><select class="select" id="submission-runtime" name="language">${availableRuntimes().map(id=>`<option value="${id}" ${profile.id===id?'selected':''}>${RUNTIME_PROFILES[id].choice}</option>`).join('')}</select></label></div>
  ${profile.experimental?`<div class="codon-choice"><strong>Đội chủ động chọn Python + Codon</strong><p>Source sẽ cần build được với Codon 0.20.3 và các API được hỗ trợ. Hiệu năng phụ thuộc bot; hãy kiểm tra tương thích và benchmark trước khi chốt.</p><label class="runtime-consent"><input type="checkbox" id="codon-consent" name="codonConsent" required ${state.draftCodonConsent?'checked':''}><span>Đội đồng ý thử Python + Codon và đã hiểu giới hạn tương thích.</span></label><div class="runtime-links"><a href="${profile.starter}" class="text-link" download>Tải bot mẫu Codon ${icon('download')}</a><a href="#/benchmark" class="text-link">Xem API đã kiểm tra ${icon('arrow')}</a></div></div>`:`<div class="runtime-default-note">${icon('check')}<span><strong>C++17 · lựa chọn mặc định</strong>Source ${profile.entry}, build trước khi chạy. Bắt đầu với STL và bộ bot mẫu C++.<a href="${profile.starter}" class="text-link" download>Tải starter C++ ${icon('download')}</a></span></div>`}</div>
  <input type="file" id="bot-file" accept=".zip,application/zip" class="screen-reader-only"><label for="bot-file" class="dropzone" id="dropzone" tabindex="0">${icon('upload')}<h3>Kéo thả gói bot vào đây</h3><p>hoặc chọn file từ máy tính của bạn</p><span class="btn small">${icon('file')}Chọn file .zip</span><small>ZIP · Tối đa 10 MB · Chỉ lưu thông tin file trong bản demo</small></label>
  ${state.pendingFile?`<div class="file-selected">${icon('file')}<div><strong>${esc(state.pendingFile.name)}</strong><small>${state.pendingFile.size} · ${profile.label} · Cần backend kiểm tra source</small></div><button type="button" class="icon-btn" data-action="clear-file" aria-label="Bỏ file đã chọn">${icon('x')}</button></div>`:''}
  <div class="form-fields"><label class="field"><span>Ghi chú phiên bản</span><textarea class="input" name="note" placeholder="Bạn đã cải thiện điều gì ở phiên bản này?" maxlength="300">${esc(state.draftNote)}</textarea></label><div id="upload-error" class="error-inline" role="alert">${esc(state.uploadError)}</div><div class="form-footer"><p>Vòng 6 đã chốt bot. Phiên bản mới dành cho luyện tập hoặc vòng tiếp theo.</p><button class="btn primary" type="submit">${icon('upload')}Lưu phiên bản demo</button></div></div></form></section>
  <section class="panel">${sectionHead('Lịch sử nộp','Runtime được lưu theo từng phiên bản của '+esc(state.teamName)+'.',`<span class="badge">${state.submissions.length} phiên bản</span>`)}<div class="table-wrap"><table><thead><tr><th>PHIÊN BẢN</th><th>THỜI GIAN</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${state.submissions.map(s=>`<tr><td><div class="submission-version">${icon('file')}<div><strong>${esc(s.version)} ${s.active?'<span class="badge success">Đang dùng</span>':''}</strong><small>${esc(s.file)}</small><small class="runtime-history">${submissionProfile(s).label}</small></div></div></td><td class="date-cell">${esc(s.date)}</td><td>${badge(s.status)}</td><td>${btn('Chi tiết','submission-detail','small','',`data-id="${esc(s.id)}"`)} ${btn('Test','benchmark-open','small','',`data-id="${esc(s.id)}" aria-label="Test & benchmark ${esc(s.version)}"`)}</td></tr>`).join('')}</tbody></table></div></section></div>
  <aside class="content-stack"><section class="panel rules-card"><h3>Gói ${profile.id==='cpp17'?'C++':'Python + Codon'} cần có gì?</h3><div class="file-tree">bot.zip<br>${profile.tree.map((file,i)=>(i===profile.tree.length-1?'└── ':'├── ')+file).join('<br>')}</div><ul class="check-list"><li>${icon('check')}${profile.entry} là entry point của bot.</li><li>${icon('check')}stdout dành cho JSON; log dùng stderr.</li><li>${icon('check')}Nộp source và dependencies, không nộp binary có sẵn.</li><li>${icon('check')}Chạy preflight theo đúng runtime đã chọn.</li></ul><h3 style="margin-top:22px;margin-bottom:8px">${profile.id==='cpp17'?'Trong bot mẫu C++':'Một số API đã thử với Codon'}</h3><div class="allowed-libs">${profile.libs.map(lib=>`<span class="code-tag">${lib}</span>`).join('')}</div><p class="runtime-small">${profile.id==='cpp17'?'Header JSON đã kèm trong starter để thử protocol offline.':'Tương thích được kiểm tra tới từng API, chưa chứng nhận toàn bộ module hoặc thư viện PyPI.'}</p>${navLink('guide','Hướng dẫn viết bot','text-link','arrow')}</section>
  <section class="panel rules-card"><h3>Quay lại C++ khi cần</h3><p class="runtime-small">Chọn C++17, dùng source C++ và nộp một phiên bản mới để test lại. Đổi runtime không tự chuyển code Python thành C++.</p><p class="runtime-small">Phiên bản đã chốt cho vòng đấu giữ nguyên runtime của nó. Việc chốt bản mới cần backend và thể lệ giải.</p>${profile.experimental?btn('Chọn C++17 mặc định','runtime-default','secondary small','arrow'):''}</section>
  <div class="technical-notice">${icon('shield')}<div><strong>Đây là lựa chọn trong bản UI demo</strong>Chỉ lưu metadata và xác nhận thử nghiệm. Chưa upload, biên dịch hay chạy source trên server.</div></div></aside></div>`;
}
